    if self.sampled is True:
        sampled = "1"
    elif self.sampled is False:
        sampled = "0"
    else:
        sampled = None

    traceparent = "%s-%s" % (self.trace_id, self.span_id)
    if sampled is not None:
        traceparent += "-%s" % (sampled,)

    return traceparent

