def capture_event(
    self,
    event: "Event",
    hint: "Optional[Hint]" = None,
    scope: "Optional[Scope]" = None,
) -> "Optional[str]":
    """Captures an event.

    :param event: A ready-made event that can be directly sent to Sentry.

    :param hint: Contains metadata about the event that can be read from `before_send`, such as the original exception object or a HTTP request object.

    :param scope: An optional :py:class:`sentry_sdk.Scope` to apply to events.

    :returns: An event ID. May be `None` if there is no DSN set or of if the SDK decided to discard the event for other reasons. In such situations setting `debug=True` on `init()` may help.
    """
    hint: "Hint" = dict(hint or ())

    if not self._should_capture(event, hint, scope):
        return None

    profile = event.pop("profile", None)

    event_id = event.get("event_id")
    if event_id is None:
        event["event_id"] = event_id = uuid.uuid4().hex
    event_opt = self._prepare_event(event, hint, scope)
    if event_opt is None:
        return None

    # whenever we capture an event we also check if the session needs
    # to be updated based on that information.
    session = scope._session if scope else None
    if session:
        self._update_session_from_event(session, event)

    is_transaction = event_opt.get("type") == "transaction"
    is_checkin = event_opt.get("type") == "check_in"

    if (
        not is_transaction
        and not is_checkin
        and not self._should_sample_error(event, hint)
    ):
        return None

    attachments = hint.get("attachments")

    trace_context = event_opt.get("contexts", {}).get("trace") or {}
    dynamic_sampling_context = trace_context.pop("dynamic_sampling_context", {})

    headers: "dict[str, object]" = {
        "event_id": event_opt["event_id"],
        "sent_at": format_timestamp(datetime.now(timezone.utc)),
    }

    if dynamic_sampling_context:
        headers["trace"] = dynamic_sampling_context

    envelope = Envelope(headers=headers)

    if is_transaction:
        if isinstance(profile, Profile):
            envelope.add_profile(profile.to_json(event_opt, self.options))
        envelope.add_transaction(event_opt)
    elif is_checkin:
        envelope.add_checkin(event_opt)
    else:
        envelope.add_event(event_opt)

    for attachment in attachments or ():
        envelope.add_item(attachment.to_envelope_item())

    return_value = None
    if self.spotlight:
        self.spotlight.capture_envelope(envelope)
        return_value = event_id

    if self.transport is not None:
        self.transport.capture_envelope(envelope)
        return_value = event_id

    return return_value

