    with new_scope():
        if is_ignored_span(name, attributes):
            return NoOpStreamedSpan(
                unsampled_reason="ignored",
            )

        if isinstance(parent_span, NoOpStreamedSpan):
            return NoOpStreamedSpan(unsampled_reason=parent_span._unsampled_reason)

