def parsed_body(self) -> "Optional[Dict[str, Any]]":
    try:
        form = self.form()
    except Exception:
        form = None
    try:
        files = self.files()
    except Exception:
        files = None

    if form or files:
        data = {}
        if form:
            data = dict(form.items())
        if files:
            for key in files.keys():
                data[key] = AnnotatedValue.removed_because_raw_data()

        return data

    return self.json()

