def auto_start(self) -> "Union[ContinuousProfile, None]":
    if not self.sampled:
        return None

    if self.lifecycle != "trace":
        return None

    logger.debug("[Profiling] Auto starting profiler")

    profile = ContinuousProfile()

    self.new_profiles.append(profile)
    self.ensure_running()

    return profile

